typedef unsigned int u_int;

typedef float nglMatrix[4][4];

struct nglTexture;
struct nglMaterialInfo
{
  u_int Hash;
  u_int DiffuseKickAddr;
  u_int DetailKickAddr;
  u_int EnvironmentKickAddr;
  u_int LightKickAddr;
  u_int CmdListEndAddr;
  u_int* BakedDMA;
};

struct nglMaterial
{
  u_int Flags;
  nglTexture* Map;
  char released_to_info[132];
  nglMaterialInfo* Info;
};

struct nglMeshSection
{
  nglMaterial* Material;
  char released_rest[60];
};

struct nglMesh
{
  u_int Flags;
  char released_to_nbones[48];
  u_int NBones;
  nglMatrix* Bones;
  u_int NSections;
  nglMeshSection* Sections;
};

enum
{
  NGLMAT_TEXTURE_MAP = 0x00000001,
  NGLMAT_LIGHT_MAP = 0x00000020,
  NGLMAT_DETAIL_MAP = 0x00000040,
  NGLMAT_ENVIRONMENT_MAP = 0x00000080,
  NGLMESH_PROCESSED = 0x00100000
};

#define NGL_TEXTURE_MASK ( NGLMAT_TEXTURE_MAP | NGLMAT_LIGHT_MAP | NGLMAT_DETAIL_MAP | NGLMAT_ENVIRONMENT_MAP )
#define SCE_MATRIX(x) ((float(*)[4])(float*)&(x))

extern nglTexture* nglWhiteTex;
extern int sceVu0InversMatrix( float Dest[4][4], float Src[4][4] );
extern void nglBindMeshTextures( nglMesh* Mesh, bool Load );
extern void* nglMemAlloc( u_int Size, u_int Align );
extern void nglBakeMaterial( nglMesh* Mesh, nglMeshSection* Section, bool Scratch );

void nglProcessMesh( nglMesh* Mesh, u_int Version )
{
  u_int i;

  // Pre-invert bone matrices.
  for ( i = 0; i < Mesh->NBones; i++ )
    sceVu0InversMatrix( SCE_MATRIX( Mesh->Bones[i] ), SCE_MATRIX( Mesh->Bones[i] ) );

  for ( i = 0; i < Mesh->NSections; i++ )
  {
    // Process the material data.
    nglMeshSection* Section = &Mesh->Sections[i];
    nglMaterial* Material = Section->Material;

    Material->Flags &= ~NGLMAT_DETAIL_MAP;

    // Automatically attach textures used by the mesh.
		if (i==0)
			nglBindMeshTextures( Mesh, true );
		else
			nglBindMeshTextures( Mesh, false );
    // Flat shaded meshes (or meshes whose textures could not be loaded) automatically receive nglWhiteTex.
    if ( !( Material->Flags & NGL_TEXTURE_MASK ) )
    {
      Material->Flags |= NGLMAT_TEXTURE_MAP;
      Material->Map = nglWhiteTex;
    }

    Material->Info = (nglMaterialInfo*)nglMemAlloc( sizeof(nglMaterialInfo), 8 );
    void nglBakeMaterial( nglMesh* Mesh, nglMeshSection* Section, bool Scratch );
    nglBakeMaterial( Mesh, Section, false );
  }


  Mesh->Flags |= NGLMESH_PROCESSED;
}
